mapper.select:
SELECT * FROM wms_inbound_manufactured where bool_delete_enum = 0
and review_status = #{reviewStatus}
and basic_class & #{ basicClass} > 0
and serial_number like CONCAT('%', #{serialNumber},'%')
and shipment_number like CONCAT('%', #{shipmentNumber},'%')
and license_plate like CONCAT('%', #{licensePlate},'%')
and create_time > #{createTime[0]}
and create_time < #{createTime[1]}
and purchase_SN like CONCAT('%', #{purchaseSN},'%')
and supplier_id = #{supplierId}
and find_in_set(#{projectId},project_ids)

mapper.update:
UPDATE wms_inbound_manufactured
SET editable = #{value}
WHERE original_id = #{id}
  and bool_delete_enum = 0
